/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *          # core scheduling primitives
from exo.libs.memories import DRAM
from exo.stdlib.scheduling import *       # helper scheduling utilities (repeat, replace_all, ...)
from exo.stdlib.stdlib import tile_loops, vectorize  # optional higher-level transforms

# -----------------------------------------------------------------------------
# Baseline GESUMMV kernel (semantics mirror the original PolyBench kernel)
#   y = alpha * (A * x) + beta * (B * x)
#
# We accumulate each output element (row i) in private scalar temporaries
# tmp_i and y_i to keep the inner reduction variables in registers. At the
# end of the row we write back to tmp[i] and y[i]. This preserves the
# original computation order over j for each i.
# -----------------------------------------------------------------------------

@proc
def kernel_gesummv_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
    tmp: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    assert n >= 1

    for i in seq(0, n):
        # Per-row accumulators kept in registers by the compiler
        tmp_i: DATA_TYPE
        y_i: DATA_TYPE

        tmp_i = 0.0
        y_i = 0.0

        for j in seq(0, n):
            tmp_i += A[i, j] * x[j]
            y_i += B[i, j] * x[j]

        # Write the finished row results back to memory
        tmp[i] = tmp_i
        y[i] = alpha * tmp_i + beta * y_i

# -----------------------------------------------------------------------------
# Scheduled / optimized version
#
# Transformations applied:
#   1. Tile the inner j loop with a fixed block size (J_TILE) to create an
#      inner loop with constant bounds that is amenable to unrolling and
#      vectorization while preserving j iteration order.
#   2. Fully unroll the j-inner loop inside each tile. Since its bound is a
#      small compile-time constant, this allows the compiler to aggressively
#      optimize and vectorize the fused FMA-like operations.
#   3. Parallelize the outer i loop. Each iteration writes to a distinct
#      row i of tmp and y and only reads shared inputs (A, B, x, alpha, beta),
#      so the loop is embarrassingly parallel. Exo lowers this to an OpenMP
#      parallel-for pragma; on compilers without OpenMP enabled, the pragma
#      is safely ignored.
#
# All transformations preserve the original mathematical result and the
# element-wise write pattern to tmp and y.
# -----------------------------------------------------------------------------

kernel_gesummv_opt = kernel_gesummv_base

# Tile size for the inner j loop. This is a compile-time tuning knob chosen
# to be friendly to SIMD widths and L1 cache lines on modern x86 CPUs.
J_TILE = 32

# 1) Tile the inner j loop: j -> (jo, ji) with ji having constant extent J_TILE.
kernel_gesummv_opt = divide_loop(
    kernel_gesummv_opt,
    "j",                 # split the inner j loop
    J_TILE,              # tile size
    ["jo", "ji"],        # new iterator names: outer and inner tile indices
    tail="guard",        # handle the n % J_TILE tail with a guarded inner loop
)

# 2) Unroll the inner-"ji" loop. Its extent is the constant J_TILE, so this
#    produces straight-line code for the main body of the dot products.
kernel_gesummv_opt = unroll_loop(kernel_gesummv_opt, "ji")

# 3) Parallelize the outer i loop. Each iteration is independent, so this is
#    safe and exposes coarse-grain parallelism to OpenMP.
kernel_gesummv_opt = parallelize_loop(kernel_gesummv_opt, "i")

# 4) Run a simplification pass to clean up the IR after tiling/unrolling.
kernel_gesummv_opt = simplify(kernel_gesummv_opt)

# 5) Expose the optimized kernel under the name expected by the C driver.
kernel_gesummv = rename(kernel_gesummv_opt, "kernel_gesummv")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to 1D pointers. */
  kernel_gesummv (/*ctxt=*/NULL, n,
		  (DATA_TYPE*)&alpha,
		  (DATA_TYPE*)&beta,
		  (DATA_TYPE*)POLYBENCH_ARRAY(A),
		  (DATA_TYPE*)POLYBENCH_ARRAY(B),
		  (DATA_TYPE*)POLYBENCH_ARRAY(tmp),
		  (DATA_TYPE*)POLYBENCH_ARRAY(x),
		  (DATA_TYPE*)POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
